func (a *App) listApprovals(w http.ResponseWriter, r *http.Request) {
	p, _ := principalFrom(r.Context())
	organizationID := ""
	if p.OrganizationID != nil {
		organizationID = *p.OrganizationID
	}
	rows, err := a.db.Query(r.Context(), `SELECT i.id,i.object_type,i.object_id,i.status,i.current_step,i.context,i.requested_by,i.created_at,d.name,d.steps,o.number,o.title,o.amount,s.name FROM workflow_instances i JOIN workflow_definitions d ON d.id=i.definition_id LEFT JOIN business_objects o ON o.id=i.object_id LEFT JOIN suppliers s ON s.id=o.supplier_id WHERE i.status='pending' AND (`+orgInScope("o.organization_id", "$1", "$2")+` OR ($1='own' AND (o.owner_id=$3::uuid OR i.requested_by=$3::uuid))) ORDER BY i.created_at`, p.DataScope, organizationID, p.ID)
	if err != nil {
		writeError(w, 500, "database_error", "승인함을 조회하지 못했습니다")
		return
	}
	defer rows.Close()
	items := []map[string]any{}
	roles, err := principalRoleCodes(r.Context(), a, p.ID)
	if err != nil {
		logDB(err)
		writeError(w, 500, "database_error", "승인함을 조회하지 못했습니다")
		return
	}
	for rows.Next() {
		var id, typ, obj, status string
		var step int
		var context, steps []byte
		var requester *string
		var created any
		var workflow string
		var number, title, supplier *string
		var amount *float64
		if err := rows.Scan(&id, &typ, &obj, &status, &step, &context, &requester, &created, &workflow, &steps, &number, &title, &amount, &supplier); err != nil {
			logDB(err)
			writeError(w, 500, "database_error", "승인함을 조회하지 못했습니다")
			return
		}
		stepList := instanceSteps(context, steps)
		if step >= len(stepList) {
			continue
		}
		current := stepList[step]
		role, _ := current["role"].(string)
		if role != "" && !roles[role] && !hasPermission(p, "*") {
			continue
		}
		var c any
		_ = json.Unmarshal(context, &c)
		items = append(items, map[string]any{"id": id, "objectType": typ, "objectId": obj, "status": status, "currentStep": step, "currentStepDefinition": current, "context": c, "requestedBy": requester, "createdAt": created, "workflowName": workflow, "number": number, "title": title, "amount": amount, "supplierName": supplier})
	}
	if err := rows.Err(); err != nil {
		logDB(err)
		writeError(w, 500, "database_error", "승인함을 조회하지 못했습니다")
		return
	}
	writeJSON(w, 200, map[string]any{"items": items})
}

// A role list that silently comes back short changes what the caller believes
// the user may approve, so a failed lookup is returned rather than swallowed.
func principalRoleCodes(ctx context.Context, a *App, userID string) (map[string]bool, error) {
	rows, err := a.db.Query(ctx, `SELECT r.code FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	roles := map[string]bool{}
	for rows.Next() {
		var code string
		if err := rows.Scan(&code); err != nil {
			return nil, err
		}
		roles[code] = true
	}
	return roles, rows.Err()
}

